contracts/SentryWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SentryWallet
 * @notice Manager-controlled custody for one identity and one immutable payment currency.
 * @dev Users never move funds directly. EmploymentManager is the sole settlement and withdrawal authority.
 *      Wallet lifecycle (Provisioning → Active → Locked → Archived) is independent of employment status.
 */
contract SentryWallet is ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Supported payment assets.
    enum Token {
        CELO,
        USDm,
        USDC,
        USDT
    }

    /// @notice Wallet lifecycle states managed by EmploymentManager.
    enum WalletStatus {
        Provisioning,
        Active,
        Locked,
        Archived
    }

    /// @notice Immutable implementation version for indexers and future factory routing.
    uint256 public constant VERSION = 1;

    /// @notice Private identity commitment associated with this wallet.
    bytes32 public immutable identityHash;

    /// @notice Manager authorized to settle, withdraw, and manage lifecycle.
    address public immutable manager;

    /// @notice Currency permanently assigned when the wallet is deployed.
    Token public immutable paymentCurrency;

    /// @notice ERC20 contract for paymentCurrency, or zero for native CELO.
    address public immutable tokenAddress;

    /// @notice Current wallet lifecycle state.
    WalletStatus public status;

    /// @notice Emitted when native CELO is received.
    event NativeReceived(address indexed from, uint256 amount);

    /// @notice Emitted when funds are deposited or synchronized into the wallet.
    /// @param wallet This wallet address.
    /// @param from Funding source.
    /// @param amount Amount received in the wallet currency.
    /// @param currency Immutable wallet currency.
    event WalletFunded(
        address indexed wallet,
        address indexed from,
        uint256 amount,
        Token currency
    );

    /// @notice Emitted after the manager executes a user withdrawal.
    event Withdrawal(
        address indexed to,
        Token indexed token,
        uint256 amount,
        bytes32 indexed withdrawalId
    );

    /// @notice Emitted after the manager executes a settlement.
    event SettlementExecuted(
        address indexed treasury,
        Token indexed token,
        uint256 amount,
        bytes32 indexed settlementId
    );

    /// @notice Emitted when wallet lifecycle changes.
    event WalletStatusChanged(
        WalletStatus indexed previousStatus,
        WalletStatus indexed newStatus
    );

    error UnauthorizedManager();
    error ZeroAddress();
    error InvalidIdentity();
    error InvalidAmount();
    error NativeTransferFailed();
    error InvalidTokenConfig();
    error InvalidWalletStatus();

    modifier onlyManager() {
        if (msg.sender != manager) revert UnauthorizedManager();
        _;
    }

    modifier onlyActive() {
        if (status != WalletStatus.Active) revert InvalidWalletStatus();
        _;
    }

    /**
     * @notice Creates a manager-controlled wallet for one identity and currency.
     * @param employmentManager Manager authorized to settle funds and manage lifecycle.
     * @param identityHash_ Namespaced identity commitment.
     * @param currency_ Immutable wallet currency.
     * @param tokenAddress_ ERC20 address, or zero for CELO.
     */
    constructor(
        address employmentManager,
        bytes32 identityHash_,
        Token currency_,
        address tokenAddress_
    ) {
        if (employmentManager == address(0)) revert ZeroAddress();
        if (identityHash_ == bytes32(0)) revert InvalidIdentity();
        if (currency_ == Token.CELO && tokenAddress_ != address(0)) revert InvalidTokenConfig();
        if (currency_ != Token.CELO && tokenAddress_ == address(0)) revert InvalidTokenConfig();

        manager = employmentManager;
        identityHash = identityHash_;
        paymentCurrency = currency_;
        tokenAddress = tokenAddress_;
        status = WalletStatus.Provisioning;
    }

    /// @notice Accepts native CELO transfers for CELO wallets.
    receive() external payable {
        if (paymentCurrency != Token.CELO) revert InvalidTokenConfig();
        emit NativeReceived(msg.sender, msg.value);
        emit WalletFunded(address(this), msg.sender, msg.value, paymentCurrency);
    }

    /// @notice Returns the balance of the wallet's immutable currency.
    function balance() external view returns (uint256) {
        if (paymentCurrency == Token.CELO) return address(this).balance;
        return IERC20(tokenAddress).balanceOf(address(this));
    }

    /// @notice Activates a newly provisioned wallet.
    function activate() external onlyManager {
        if (status != WalletStatus.Provisioning) revert InvalidWalletStatus();
        _setStatus(WalletStatus.Active);
    }

    /// @notice Locks an active wallet to block settlements and withdrawals.
    function lockWallet() external onlyManager {
        if (status != WalletStatus.Active) revert InvalidWalletStatus();
        _setStatus(WalletStatus.Locked);
    }

    /// @notice Unlocks a locked wallet.
    function unlockWallet() external onlyManager {
        if (status != WalletStatus.Locked) revert InvalidWalletStatus();
        _setStatus(WalletStatus.Active);
    }

    /// @notice Archives a wallet permanently.
    function archiveWallet() external onlyManager {
        if (status == WalletStatus.Archived) revert InvalidWalletStatus();
        _setStatus(WalletStatus.Archived);
    }

    /**
     * @notice Records an ERC20 funding event after backend synchronization.
     * @param from Funding source observed off-chain or on-chain.
     * @param amount Amount credited in the wallet currency.
     */
    function notifyFunding(address from, uint256 amount) external onlyManager {
        if (amount == 0) revert InvalidAmount();
        emit WalletFunded(address(this), from, amount, paymentCurrency);
    }

    /**
     * @notice Transfers an authorized batch settlement to the treasury.
     * @dev Replay protection and employment validation are enforced by EmploymentManager.
     */
    function executeSettlement(
        address treasury,
        uint256 amount,
        bytes32 settlementId
    ) external onlyManager onlyActive nonReentrant {
        if (treasury == address(0)) revert ZeroAddress();
        if (amount == 0) revert InvalidAmount();
        _transfer(treasury, amount);
        emit SettlementExecuted(treasury, paymentCurrency, amount, settlementId);
    }

    /**
     * @notice Transfers available funds to a user destination.
     * @param destination Registered withdrawal destination.
     * @param amount Amount to transfer.
     * @param withdrawalId Unique withdrawal identifier.
     */
    function withdrawTo(
        address destination,
        uint256 amount,
        bytes32 withdrawalId
    ) external onlyManager onlyActive nonReentrant {
        if (destination == address(0)) revert ZeroAddress();
        if (amount == 0) revert InvalidAmount();
        _transfer(destination, amount);
        emit Withdrawal(destination, paymentCurrency, amount, withdrawalId);
    }

    function _setStatus(WalletStatus newStatus) private {
        WalletStatus previousStatus = status;
        if (previousStatus == newStatus) revert InvalidWalletStatus();
        status = newStatus;
        emit WalletStatusChanged(previousStatus, newStatus);
    }

    function _transfer(address destination, uint256 amount) private {
        if (paymentCurrency == Token.CELO) {
            (bool ok, ) = payable(destination).call{value: amount}("");
            if (!ok) revert NativeTransferFailed();
        } else {
            IERC20(tokenAddress).safeTransfer(destination, amount);
        }
    }
}

contracts/SentryWalletFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {SentryWallet} from "./SentryWallet.sol";

/**
 * @title SentryWalletFactory
 * @notice Deploys exactly one SentryWallet for each identity and user key.
 * @dev Uses CREATE deliberately. Future wallet implementations only require updating
 *      `walletVersion` and the deployment target in this factory — no in-place upgrades.
 */
contract SentryWalletFactory is Ownable {
    enum Token {
        CELO,
        USDm,
        USDC,
        USDT
    }

    struct CurrencyConfig {
        address tokenAddress;
        bool enabled;
    }

    /// @notice Emitted after a wallet is created and indexed.
    /// @param identityHash Identity commitment assigned to the wallet.
    /// @param userKey Stable user identifier.
    /// @param currency Immutable wallet currency.
    /// @param wallet Deployed SentryWallet address.
    event WalletCreated(
        bytes32 indexed identityHash,
        address indexed userKey,
        Token currency,
        address indexed wallet
    );

    /// @notice Emitted when a currency is enabled or disabled for future wallets.
    /// @param currency Currency configuration changed.
    /// @param enabled New enabled state.
    event CurrencyEnabled(Token indexed currency, bool enabled);
    event TokenAddressUpdated(
        Token indexed currency,
        address indexed previousAddress,
        address indexed newAddress
    );

    /// @notice An identity already has a wallet.
    error IdentityAlreadyRegistered();

    /// @notice An owner already has a wallet.
    error OwnerAlreadyRegistered();

    /// @notice Address argument cannot be zero.
    error ZeroAddress();

    /// @notice Identity hash cannot be zero.
    error InvalidIdentity();
    error CurrencyDisabled();
    error InvalidTokenConfig();

    /// @notice EmploymentManager assigned to every deployed wallet.
    address public immutable manager;

    /// @notice Version of SentryWallet deployed by this factory.
    uint256 public walletVersion = 1;

    mapping(Token currency => CurrencyConfig config) public currencies;

    /// @notice Wallet indexed by identity commitment.
    mapping(bytes32 identityHash => address wallet) public walletOfIdentity;

    /// @notice Wallet indexed by owner.
    mapping(address userKey => address wallet) public walletOfUser;

    /// @notice Identity commitment indexed by wallet.
    mapping(address wallet => bytes32 identityHash) public identityOfWallet;

    /**
     * @notice Configures the wallet factory.
     * @param initialOwner Account authorized to create wallets and update token addresses.
     * @param employmentManager Manager assigned to new wallets.
     * @param usdm_ Initial USDm token address.
     * @param usdc_ Initial USDC token address.
     * @param usdt_ Initial USDT token address.
     */
    constructor(
        address initialOwner,
        address employmentManager,
        address usdm_,
        address usdc_,
        address usdt_
    ) Ownable(initialOwner) {
        _validateAddresses(employmentManager, usdm_, usdc_, usdt_);
        manager = employmentManager;
        currencies[Token.CELO] = CurrencyConfig(address(0), true);
        currencies[Token.USDm] = CurrencyConfig(usdm_, true);
        currencies[Token.USDC] = CurrencyConfig(usdc_, true);
        currencies[Token.USDT] = CurrencyConfig(usdt_, true);
    }

    /**
     * @notice Creates and indexes a wallet.
     * @param identityHash Identity commitment for the user.
     * @param userKey Stable on-chain user identifier.
     * @param currency Immutable currency selected for the wallet.
     * @return wallet Address of the deployed wallet.
     */
    function createWallet(
        bytes32 identityHash,
        address userKey,
        Token currency
    ) external onlyOwner returns (address wallet) {
        if (userKey == address(0)) revert ZeroAddress();
        if (identityHash == bytes32(0)) revert InvalidIdentity();
        if (walletOfIdentity[identityHash] != address(0)) revert IdentityAlreadyRegistered();
        if (walletOfUser[userKey] != address(0)) revert OwnerAlreadyRegistered();

        CurrencyConfig memory config = currencies[currency];
        if (!config.enabled) revert CurrencyDisabled();
        if (currency != Token.CELO && config.tokenAddress == address(0)) {
            revert InvalidTokenConfig();
        }

        wallet = address(new SentryWallet(
            manager,
            identityHash,
            SentryWallet.Token(uint8(currency)),
            config.tokenAddress
        ));

        walletOfIdentity[identityHash] = wallet;
        walletOfUser[userKey] = wallet;
        identityOfWallet[wallet] = identityHash;

        emit WalletCreated(identityHash, userKey, currency, wallet);
    }

    /**
     * @notice Checks whether an identity has a wallet.
     * @param identityHash Identity commitment to query.
     * @return exists True when a wallet is registered.
     */
    function hasWallet(bytes32 identityHash) external view returns (bool exists) {
        return walletOfIdentity[identityHash] != address(0);
    }

    /**
     * @notice Resolves a wallet from an identity.
     * @param identityHash Identity commitment to query.
     * @return wallet Registered wallet or zero address.
     */
    function walletFromIdentity(bytes32 identityHash) external view returns (address wallet) {
        return walletOfIdentity[identityHash];
    }

    /**
     * @notice Resolves a wallet from its stable user key.
     * @param userKey User key to query.
     * @return wallet Registered wallet or zero address.
     */
    function walletFromUser(address userKey) external view returns (address wallet) {
        return walletOfUser[userKey];
    }

    function setCurrencyEnabled(Token currency, bool enabled) external onlyOwner {
        CurrencyConfig storage config = currencies[currency];
        if (currency != Token.CELO && config.tokenAddress == address(0)) {
            revert InvalidTokenConfig();
        }
        if (config.enabled == enabled) return;
        config.enabled = enabled;
        emit CurrencyEnabled(currency, enabled);
    }

    function updateTokenAddress(Token currency, address newAddress) external onlyOwner {
        if (currency == Token.CELO || newAddress == address(0)) revert InvalidTokenConfig();
        CurrencyConfig storage config = currencies[currency];
        address previousAddress = config.tokenAddress;
        if (previousAddress == newAddress) return;
        config.tokenAddress = newAddress;
        emit TokenAddressUpdated(currency, previousAddress, newAddress);
    }

    /**
     * @dev Validates manager and token addresses.
     * @param employmentManager Manager address.
     * @param usdm_ USDm address.
     * @param usdc_ USDC address.
     * @param usdt_ USDT address.
     */
    function _validateAddresses(
        address employmentManager,
        address usdm_,
        address usdc_,
        address usdt_
    ) private pure {
        if (
            employmentManager == address(0) ||
            usdm_ == address(0) ||
            usdc_ == address(0) ||
            usdt_ == address(0)
        ) revert ZeroAddress();
    }
}
